mapper.select:
select shu.*, shut.role, shut.uuid as type_uuid, T.max_manifest_update_time, T.status, T.dc_reply, T.zc_reply from safety_hazard_user shu left join safety_hazard_user_type shut on shu.type_id = shut.id left join ( select sc.user_id, MAX(sc.update_time) AS max_manifest_update_time, sc.status, sr.dc_reply, sr.zc_reply FROM safety_hazard_manifest_school sc LEFT JOIN safety_hazard_manifest_reply sr ON sc.id = sr.manifest_id GROUP BY sc.user_id ) T ON shu.user_id = T.user_id
and shu.user_name like concat('%', #{userName}, '%') and shu.contact = #{contact} and shu.wx_phone = #{wxPhone} and shu.address = #{address} and shu.type_id = #{typeId} and shu.property = #{property} and shu.sort_num = #{sortNum} and shu.contact_group like concat('%', #{contactGroup}, '%') and shut.role = #{role}
order by max_manifest_update_time desc

mapper.update:
update safety_hazard_user
user_name = #{userName}, contact = #{contact}, wx_phone = #{wxPhone}, address = #{address}, type_id = #{typeId}, property = #{property}, sort_num = #{sortNum}, contact_group = #{contactGroup}, create_time = #{createTime}, update_time = #{updateTime},
where user_id = #{userId}

