mapper.select:
select shu.user_name as userName, T.status as status, T.max_manifest_update_time as maxManifestUpdateTime, T.contact as contact, T.wx_phone as wxPhone, shuu.user_name as parentName, T.dc_reply as dcReply, T.zc_reply as zcReply from safety_hazard_user shu left join safety_hazard_user_type shut on shu.type_id = shut.id left join safety_hazard_user shuu on shu.parent_id = shuu.user_id left join ( select sc.user_id, MAX(sc.update_time) AS max_manifest_update_time, sc.contact, sc.wx_phone, sc.status, sr.dc_reply, sr.zc_reply FROM safety_hazard_manifest_school sc LEFT JOIN safety_hazard_manifest_reply sr ON sc.id = sr.manifest_id GROUP BY sc.user_id ) T ON shu.user_id = T.user_id
and shu.user_name like concat('%', #{userName}, '%') and shu.contact = #{contact} and shu.wx_phone = #{wxPhone} and shu.address = #{address} and shu.type_id = #{typeId} and shu.property = #{property} and shu.sort_num = #{sortNum} and shu.contact_group like concat('%', #{contactGroup}, '%') and shut.role = #{role}
order by max_manifest_update_time desc
